Write a C program to find the sum of all digits of a given number

### Response:
#include <stdio.h>

int getSumOfDigits(int num) {
    // Initialize sum
    int sum = 0;

    // Find the sum of digits
    while(num > 0) {
        sum += num % 10;
        num /= 10;
    }

    return sum;
}

int main() {
    int num;
    scanf("%d", &num);

    printf("Sum of digits of %d is %d\n", num, getSumOfDigits(num));

    return 0;
}

